/// NFKD + strip of combining diacritical marks (U+0300–U+036F) for the
/// characters that matter in storage file names.
String foldNfkdForFileName(String value) {
  final buffer = StringBuffer();
  for (final rune in value.runes) {
    if (rune >= 0x300 && rune <= 0x36F) continue;
    final folded = kNfkdAsciiFold[rune];
    if (folded != null) {
      buffer.write(folded);
    } else {
      buffer.writeCharCode(rune);
    }
  }
  return buffer.toString();
}
